const local=([lng,lat])=>[(lng-ORIGIN[0])*LNG_SCALE,(lat-ORIGIN[1])*LAT_SCALE];
const mat=(color)=>new THREE.MeshLambertMaterial({color,flatShading:true});
function cylinder(r1,r2,h,color,z=0,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat(color));m.rotation.x=Math.PI/2;m.position.z=z+h/2;return m;}
function box(w,d,h,color,z=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,d,h),mat(color));m.position.z=z+h/2;return m;}
function sphere(r,color,z){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(r,2),mat(color));m.position.z=z;return m;}
function pearl(){const g=new THREE.Group();for(let i=0;i<3;i++){const a=i*Math.PI*2/3;const c=cylinder(5,9,275,'#b6c6c0',0);c.position.x=Math.sin(a)*19;c.position.y=Math.cos(a)*19;g.add(c);}g.add(sphere(48,'#bc6a63',95),sphere(27,'#bd6e68',273),cylinder(8,13,90,'#d3c9b4',288),sphere(8,'#ca8568',350),cylinder(0.8,3.7,89,'#cecfb9',378));for(const [r,z] of [[47,94],[26.5,272]]){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,3.8,6,32),mat('#5e858b'));ring.position.z=z;g.add(ring);}return g;}
function tower(){const g=new THREE.Group();for(let i=0;i<38;i++){const h=15.5,r=38-i*.65;const block=box(r*1.5,r*1.5,h,'#abc4bf',i*h);block.rotation.z=i*.026;g.add(block);}g.add(cylinder(12,18,43,'#c7d6c7',589));return g;}
function swfc(){const g=new THREE.Group(),shape=new THREE.Shape();shape.moveTo(-30,0);shape.lineTo(30,0);shape.lineTo(20,492);shape.lineTo(-20,492);shape.closePath();const hole=new THREE.Path();hole.moveTo(-12,440);hole.lineTo(12,440);hole.lineTo(14,474);hole.lineTo(-14,474);hole.closePath();shape.holes.push(hole);const mesh=new THREE.Mesh(new THREE.ExtrudeGeometry(shape,{depth:30,bevelEnabled:false}),mat('#88abb2'));mesh.rotation.x=Math.PI/2;mesh.position.y=15;g.add(mesh);for(let z=30;z<430;z+=28)g.add(box(52,31,1.7,'#b3c9c5',z));return g;}
function jinmao(){const g=new THREE.Group();let z=0;for(let i=0;i<16;i++){let r=30-i*1.45,h=28-i*.8;g.add(cylinder(r*.92,r,h,'#b8c3b7',z,8));g.add(cylinder(r+2,r+2,2.5,'#8c9f98',z+h-2,8));z+=h;}g.add(cylinder(.7,8,75,'#b5bbaa',z));return g;}
function createPlane(){const group=new THREE.Group(),cream=mat('#f4db9e'),red=mat('#ad553c'),dark=mat('#607d79');const body=new THREE.Mesh(new THREE.CapsuleGeometry(2,18,3,7),cream);body.scale.set(1,1,.8);group.add(body);const fuselage=box(3.8,24,3.5,'#f2d79c',0);fuselage.position.z=0;group.add(fuselage);const wing=box(32,5,1.1,'#b65f43',0);wing.position.y=1;group.add(wing);const tail=box(12,3,0.9,'#b65f43',0);tail.position.y=-9;tail.position.z=2;group.add(tail);const fin=box(1,5,5,'#b65f43',0);fin.position.y=-9;fin.position.z=3;group.add(fin);const cockpit=new THREE.Mesh(new THREE.SphereGeometry(2.4,8,6),dark);cockpit.position.set(0,4,2);cockpit.scale.set(1,1.7,.7);group.add(cockpit);const prop=box(10,.5,.6,'#566e65',0);prop.position.y=14;prop.position.z=0;group.add(prop);group.userData.prop=prop;return group;}
export function createCityLayer(map){
 const mc=maplibregl.MercatorCoordinate.fromLngLat(ORIGIN,0),scale=mc.meterInMercatorCoordinateUnits();
 const city={id:'city-models',type:'custom',renderingMode:'3d',mode:'miniature',flight:null,
 onAdd(map,gl){this.map=map;this.camera=new THREE.Camera();this.scene=new THREE.Scene();this.scene.add(new THREE.AmbientLight(0xfffae4,2));const sun=new THREE.DirectionalLight(0xfff2d3,3);sun.position.set(-500,-700,1000);this.scene.add(sun);this.landmarkGroup=new THREE.Group();this.scene.add(this.landmarkGroup);for(const l of landmarks.filter(l=>l.model)){const g=({pearl,tower,swfc,jinmao})[l.model]();const xy=local(l.coord);g.position.set(...xy,0);this.landmarkGroup.add(g);}this.treeGroup=new THREE.Group();this.scene.add(this.treeGroup);this.plane=createPlane();this.plane.visible=false;this.scene.add(this.plane);this.shadow=new THREE.Mesh(new THREE.CircleGeometry(1,16),new THREE.MeshBasicMaterial({color:'#334c3d',transparent:true,opacity:.23,depthWrite:false}));this.shadow.scale.set(22,13,1);this.shadow.visible=false;this.scene.add(this.shadow);this.renderer=new THREE.WebGLRenderer({canvas:map.getCanvas(),context:gl,antialias:true});this.renderer.autoClear=false;this.renderer.outputColorSpace=THREE.SRGBColorSpace;},
 render(gl,args){this.landmarkGroup.visible=this.mode==='miniature'&&map.getZoom()>13;this.treeGroup.visible=this.mode==='miniature'&&map.getZoom()>14.3;const f=this.flight;this.plane.visible=!!f;this.shadow.visible=!!f;if(f){const [x,y]=local(f.position);this.plane.position.set(x,y,f.altitude);this.plane.rotation.z=-f.heading*Math.PI/180;this.plane.rotation.y=-f.bank*.3;let size=Math.max(1,Math.pow(2,15.5-map.getZoom())*1.4);this.plane.scale.setScalar(size);this.plane.userData.prop.rotation.y=performance.now()*.07;this.shadow.position.set(x+f.altitude*.22,y-f.altitude*.16,3);this.shadow.rotation.z=-f.heading*Math.PI/180;this.shadow.scale.set(20*size,12*size,1);}
 const matrix=args.defaultProjectionData.mainMatrix;const m=new THREE.Matrix4().fromArray(matrix),t=new THREE.Matrix4().makeTranslation(mc.x,mc.y,mc.z).scale(new THREE.Vector3(scale,-scale,scale));this.camera.projectionMatrix=m.multiply(t);this.camera.projectionMatrixInverse.copy(this.camera.projectionMatrix).invert();this.renderer.resetState();this.renderer.render(this.scene,this.camera);if(f&&!f.paused)this.map.triggerRepaint();},
 setMode(mode){this.mode=mode;map.triggerRepaint();},
 setTrees(points){if(!this.scene)return;this.treeGroup.children.forEach(x=>{x.geometry.dispose();x.material.dispose();});this.treeGroup.clear();if(!points.length)return;const crowns=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,1),mat('#668b49'),points.length),trunks=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,5).rotateX(Math.PI/2),mat('#8a8260'),points.length),d=new THREE.Object3D();points.forEach((p,i)=>{const [x,y]=local(p);let r=4.5+(Math.sin(x*7+y*13)*.5+.5)*4;d.position.set(x,y,r+3);d.scale.set(r,r,r*1.15);d.updateMatrix();crowns.setMatrixAt(i,d.matrix);crowns.setColorAt(i,new THREE.Color(['#638d4a','#789b52','#547e43','#8aa85f'][i%4]));d.position.set(x,y,3);d.scale.set(1,1,6);d.updateMatrix();trunks.setMatrixAt(i,d.matrix);});crowns.instanceMatrix.needsUpdate=true;this.treeGroup.add(trunks,crowns);map.triggerRepaint();},
 onRemove(){this.scene?.traverse(o=>{o.geometry?.dispose();if(o.material)(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose());});this.renderer?.dispose();}
 };return city;
}
export function pointInRing(point,ring){let c=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){let a=ring[i],b=ring[j];if((a[1]>point[1])!==(b[1]>point[1])&&point[0]<(b[0]-a[0])*(point[1]-a[1])/(b[1]-a[1])+a[0])c=!c;}return c;}
export function collectTrees(map){if(map.getZoom()<14.3)return[];const fs=map.queryRenderedFeatures({layers:['park','landcover_wood','landcover_grass'].filter(id=>map.getLayer(id))}),points=[],seen=new Set(),center=map.getCenter();for(const f of fs){if(!['Polygon','MultiPolygon'].includes(f.geometry.type))continue;const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];for(const poly of polys){const ring=poly[0];if(!Array.isArray(ring)||ring.length<3||!Array.isArray(ring[0]))continue;let xs=ring.map(p=>p[0]),ys=ring.map(p=>p[1]);let x0=Math.max(Math.min(...xs),center.lng-.018),x1=Math.min(Math.max(...xs),center.lng+.018),y0=Math.max(Math.min(...ys),center.lat-.015),y1=Math.min(Math.max(...ys),center.lat+.015);const step=.0003;for(let x=Math.ceil(x0/step)*step;x<x1;x+=step)for(let y=Math.ceil(y0/step)*step;y<y1;y+=step){const px=x+Math.sin(x*930000+y*210000)*.00009,py=y+Math.cos(y*650000)*.00008,k=px.toFixed(5)+','+py.toFixed(5);if(!seen.has(k)&&pointInRing([px,py],ring)&&!poly.slice(1).some(h=>pointInRing([px,py],h))){points.push([px,py]);seen.add(k);}if(points.length>=1000)return points;}}}return points;}
